<?php
require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_once __DIR__.'/../filters.php';require_once __DIR__.'/../import_service.php';require_staff();$preview=$_SESSION['import_preview']??null;
if(isset($_GET['template'])){$kind=request_string($_GET,'template');$cols=import_templates()[$kind]??throw new DomainException('Invalid template.');output_csv($kind.'-template.csv',[],array_combine($cols,$cols));}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    verify_csrf();try{
        $action=request_string($_POST,'action');$kind=request_string($_POST,'kind');if(!isset(import_templates()[$kind]))throw new DomainException('Choose an import type.');
        if($action==='preview'){
            $f=$_FILES['csv']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024||!is_uploaded_file($f['tmp_name'])||strtolower(pathinfo($f['name'],PATHINFO_EXTENSION))!=='csv')throw new DomainException('Choose a CSV file no larger than 2 MB.');
            $data=read_import_csv($f['tmp_name'],$kind);$errors=preview_import($kind,$data);$_SESSION['import_preview']=['kind'=>$kind,'rows'=>$data,'errors'=>$errors,'created'=>time(),'token'=>bin2hex(random_bytes(16))];redirect('import.php');
        }elseif($action==='commit'){
            $p=$_SESSION['import_preview']??null;if(!$p||$p['kind']!==$kind||$p['errors']||time()-$p['created']>900||!hash_equals($p['token'],request_string($_POST,'token')))throw new DomainException('Import preview is invalid or expired. Upload and preview again.');
            $count=commit_import($kind,$p['rows']);unset($_SESSION['import_preview']);flash('success',"Imported $count records. All rows were revalidated and committed together.");redirect('import.php');
        }elseif($action==='export'){
            if($kind==='grades'){[$where,$params]=grade_filters($_POST);$data=rows(grade_select()." WHERE $where",$params);$cols=['id'=>'Grade ID','student_number'=>'Student number','offering_id'=>'Offering ID','midterm'=>'Midterm','final'=>'Final','gpa'=>'ISU grade','remarks'=>'Result','workflow'=>'Workflow'];}
            else{[$where,$params]=record_scope($kind);$data=rows("SELECT r.* FROM `$kind` r WHERE $where",$params);$cols=array_combine(import_templates()[$kind],import_templates()[$kind]);}
            audit('csv_export',$kind,null,'Exported authorized '.$kind,null,['rows'=>count($data)]);output_csv($kind.'-'.date('Ymd-His').'.csv',$data,$cols);
        }else throw new DomainException('Unknown import action.');
    }catch(DomainException $e){flash('danger',$e->getMessage());}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;flash('danger','Import was rolled back because records changed or duplicate data was found. Preview again.');}
}
page_start('Import and export','Download a template, preview validation results, then confirm the batch. Maximum 500 rows.');
?><section class="panel"><h2>CSV templates</h2><p>Use database IDs from Academic setup and class lists. Imports create new draft records; they cannot overwrite or publish grades.</p><?php foreach(import_templates()as $key=>$cols){if($key==='students'&&!is_admin())continue;echo '<a class="btn btn-outline-primary me-2" href="?template='.h($key).'">'.h(ucfirst($key)).' template</a>'; }?></section><div class="two-column"><section class="panel"><h2>Upload and preview</h2><form method="post" enctype="multipart/form-data" class="form-grid"><?php csrf_field();$kinds=['enrollments'=>'Enrollment','grades'=>'Draft grades'];if(is_admin())$kinds=['students'=>'Students']+$kinds;select_field('kind','Import type',$kinds);input_field('csv','CSV file (max 2 MB)','','file',true,'accept=".csv"');?><button class="btn btn-primary" name="action" value="preview">Validate and preview</button></form></section><section class="panel"><h2>Export authorized records</h2><form method="post" class="form-grid"><?php csrf_field();select_field('kind','Export type',['students'=>'Students','enrollments'=>'Enrollment','grades'=>'Grades']);?><button class="btn btn-outline-primary" name="action" value="export">Download CSV</button></form><p class="small text-secondary mt-3">Exports respect your current record permissions and escape spreadsheet formulas.</p></section></div>
<?php if($preview):?><section class="panel"><h2>Preview · <?=h($preview['kind'])?></h2><p><?=count($preview['rows'])?> rows · <?=count($preview['errors'])?> errors · expires after 15 minutes.</p><?php if($preview['errors']):?><div class="alert alert-danger"><?php foreach($preview['errors']as $line=>$error)echo '<p>Row '.(int)$line.': '.h($error).'</p>';?></div><?php else:?><form method="post" data-confirm="Import all validated rows? Permissions and data will be rechecked."><?php csrf_field();?><input type="hidden" name="kind" value="<?=h($preview['kind'])?>"><input type="hidden" name="token" value="<?=h($preview['token'])?>"><button class="btn btn-success" name="action" value="commit">Confirm import</button></form><?php endif;data_table(array_slice($preview['rows'],0,50),array_combine(import_templates()[$preview['kind']],import_templates()[$preview['kind']]));if(count($preview['rows'])>50)echo '<p>Showing the first 50 rows. Validation covers the full file.</p>';?></section><?php endif;page_end();
